changeSet.sql:
CREATE SEQUENCE IF NOT EXISTS public.domain_ownership_catalog_id_seq
    INCREMENT BY 1 NO MINVALUE NO MAXVALUE START WITH 1 CACHE 1;
CREATE TABLE public.domain_ownership_catalog (
    id bigint DEFAULT nextval('public.domain_ownership_catalog_id_seq'::regclass) NOT NULL,
    tenant_id character varying(255),
    code character varying(64) NOT NULL,
    label character varying(255) NOT NULL,
    hint character varying(255),
    sort_order integer DEFAULT 0 NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT domain_ownership_catalog_pkey PRIMARY KEY (id),
    CONSTRAINT fk_domain_ownership_catalog__tenant_id FOREIGN KEY (tenant_id) REFERENCES public.tenant_organization(tenant_id) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE UNIQUE INDEX ux_domain_ownership_catalog__global_code ON public.domain_ownership_catalog (code) WHERE tenant_id IS NULL;
CREATE UNIQUE INDEX ux_domain_ownership_catalog__tenant_code ON public.domain_ownership_catalog (tenant_id, code) WHERE tenant_id IS NOT NULL;
CREATE INDEX idx_domain_ownership_catalog_tenant_active ON public.domain_ownership_catalog (tenant_id, is_active, sort_order);
COMMENT ON TABLE public.domain_ownership_catalog IS 'Assignable tenant_onboarding_request.domain_ownership. Null tenant_id is the shared catalog.';
CREATE TRIGGER trg_domain_ownership_catalog_updated_at
    BEFORE UPDATE ON public.domain_ownership_catalog
    FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

INSERT INTO public.domain_ownership_catalog (tenant_id, code, label, hint, sort_order, is_active, created_at, updated_at)
SELECT NULL, seed.code, seed.label, seed.hint, seed.sort_order, true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM (VALUES
    ('CUSTOMER_REGISTRAR', 'I already own this domain (at my own registrar)', 'Customer keeps the registrar. Paste name servers and forwarding notes on the request.', 1),
    ('PLATFORM_REGISTERS', 'Please register the domain for me', 'The platform registers the domain and creates DNS.', 2),
    ('ALREADY_IN_PLATFORM', 'The domain is already managed by your team', 'DNS is already on the platform. Confirm the hosted zone before changing records.', 3)
) AS seed(code, label, hint, sort_order)
WHERE NOT EXISTS (
    SELECT 1 FROM public.domain_ownership_catalog existing
    WHERE existing.code = seed.code AND existing.tenant_id IS NULL
);
ALTER TABLE public.tenant_onboarding_request DROP CONSTRAINT IF EXISTS chk_tenant_onboarding_request__domain_ownership;
ALTER TABLE public.tenant_onboarding_request ALTER COLUMN domain_ownership TYPE character varying(64);
ALTER TABLE public.tenant_onboarding_request ADD COLUMN IF NOT EXISTS registrar_notes text;
ALTER TABLE public.tenant_onboarding_request ADD COLUMN IF NOT EXISTS source_organization_id bigint;
CREATE INDEX IF NOT EXISTS idx_tenant_onboarding_request_source_org ON public.tenant_onboarding_request (source_organization_id);
COMMENT ON COLUMN public.tenant_onboarding_request.domain_ownership IS 'Code from domain_ownership_catalog. Shared rows use a null tenant_id.';
COMMENT ON COLUMN public.tenant_onboarding_request.registrar_notes IS 'Optional paste of registrar name, domain, name servers, and URL forwarding notes. Kept on the request for later DNS work.';
COMMENT ON COLUMN public.tenant_onboarding_request.source_organization_id IS 'tenant_organization.id chosen when the request starts from an existing organization. Not a foreign key, so deleting the organization keeps the request.';
